import { createClient } from '@supabase/supabase-js'
import { randomInt } from 'crypto'
import { NextRequest, NextResponse } from 'next/server'
import { getConsumerSessionFromRequest } from '@/lib/session'
import { getTierPrice } from '@/lib/pricing'
import { normalizePhone } from '@/lib/phone'
import { DELIVERY_FEE_RUPEES } from '@/lib/delivery-fee'

export const runtime = 'nodejs'
export const dynamic = 'force-dynamic'

type IncomingItem = { listingId: string; qty: number }

// 4-digit handover code, generated server-side at order placement. The
// customer reads it off their order page to whoever hands over the goods —
// the rider (home delivery) or the farmer (self-pickup) — who confirms it in
// their dashboard. crypto.randomInt avoids Math.random's predictability.
function generateHandoverOtp(): string {
  return String(randomInt(0, 10000)).padStart(4, '0')
}

type ListingRow = {
  id: string
  name: string
  unit: string | null
  stock_qty: number | null
  farmer_id: string
  price_tier_1_qty: number | null
  price_tier_1_price: number | null
  price_tier_2_qty: number | null
  price_tier_2_price: number | null
  price_tier_3_price: number | null
}

const UUID_RE = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

function bad(msg: string, status = 400) {
  return NextResponse.json({ error: msg }, { status })
}

export async function POST(req: NextRequest) {
  const session = getConsumerSessionFromRequest(req)
  if (!session) return bad('Please log in to place an order.', 401)

  const body = await req.json().catch(() => null) as
    | {
        farmerId?: string
        paymentMethod?: string
        pickupLocation?: string | null
        pickupDay?: string | null
        items?: IncomingItem[]
        deliveryType?: string
        deliveryAddress?: string | null
        deliveryLandmark?: string | null
        deliveryPincode?: string | null
        deliveryAltPhone?: string | null
        idempotencyKey?: string | null
      }
    | null

  if (!body) return bad('Invalid request body.')
  // pickupDay is currently UI-only (not a DB column); accept and ignore.
  const { farmerId, paymentMethod, pickupLocation, items } = body
  // Optional idempotency key (a client-generated UUID per checkout attempt).
  const idempotencyKey = typeof body.idempotencyKey === 'string' && UUID_RE.test(body.idempotencyKey)
    ? body.idempotencyKey
    : null

  if (!farmerId || !UUID_RE.test(farmerId)) return bad('Invalid farmer.')
  if (paymentMethod !== 'upi' && paymentMethod !== 'cod' && paymentMethod !== 'razorpay') {
    return bad('Invalid payment method.')
  }
  if (!Array.isArray(items) || items.length === 0) return bad('Cart is empty.')
  if (items.length > 50) return bad('Too many items.')
  for (const it of items) {
    if (!it || typeof it !== 'object') return bad('Invalid item.')
    if (!it.listingId || !UUID_RE.test(it.listingId)) return bad('Invalid listing id.')
    if (!Number.isFinite(it.qty) || it.qty <= 0 || it.qty > 10000) return bad('Invalid quantity.')
  }

  const deliveryType = body.deliveryType === 'home_delivery' ? 'home_delivery' : 'self_pickup'
  let deliveryAddress: string | null = null
  let deliveryLandmark: string | null = null
  let deliveryPincode: string | null = null
  let deliveryAltPhone: string | null = null

  if (deliveryType === 'home_delivery') {
    deliveryAddress = String(body.deliveryAddress ?? '').trim().slice(0, 400)
    deliveryLandmark = String(body.deliveryLandmark ?? '').trim().slice(0, 200) || null
    const rawPincode = String(body.deliveryPincode ?? '').trim()
    deliveryPincode = /^\d{6}$/.test(rawPincode) ? rawPincode : null
    const altPhone = normalizePhone(body.deliveryAltPhone)
    deliveryAltPhone = altPhone || null

    if (!deliveryAddress) return bad('Enter your delivery address.')
    if (deliveryAddress.length < 10) return bad('Delivery address looks too short. Please add door no, street, and area.')
    if (!deliveryPincode) return bad('Enter a valid 6-digit pincode.')
  }

  const supabase = createClient(
    process.env.NEXT_PUBLIC_SUPABASE_URL!,
    process.env.SUPABASE_SERVICE_ROLE_KEY!,
  )

  // Authoritative consumer profile (we never trust the client for buyer name/phone)
  const { data: consumer } = await supabase
    .from('consumers_auth')
    .select('id, name, phone')
    .eq('id', session.consumerId)
    .maybeSingle()

  if (!consumer) return bad('Account not found. Please log in again.', 401)

  // Idempotency: if this checkout attempt was already saved (double-tap or a
  // retry after a lost response), return the existing rows instead of placing
  // a second order and decrementing stock again.
  if (idempotencyKey) {
    const { data: existing } = await supabase
      .from('orders')
      .select('id, order_code, total_price, delivery_fee')
      .eq('idempotency_key', idempotencyKey)
      .eq('consumer_id', consumer.id)
    if (existing && existing.length > 0) {
      const existingTotal = existing.reduce((s, o) => s + (Number(o.total_price) || 0), 0)
      const existingFee = existing.reduce((s, o) => s + (Number(o.delivery_fee) || 0), 0)
      return NextResponse.json({
        ok: true,
        orderIds: existing.map((r) => r.id),
        orderCodes: existing.map((r) => (r as { order_code?: string | null }).order_code).filter(Boolean),
        total: existingTotal,
        deliveryFee: existingFee,
        grandTotal: existingTotal + existingFee,
        deduplicated: true,
      })
    }
  }

  // Farmer COD acceptance check
  const { data: farmer } = await supabase
    .from('farmers')
    .select('id, cod_enabled')
    .eq('id', farmerId)
    .maybeSingle()

  if (!farmer) return bad('Farmer not found.', 404)
  if (paymentMethod === 'cod' && farmer.cod_enabled !== true) {
    return bad('This farmer is not accepting Cash on Delivery.')
  }

  // Pull live listing rows — never trust prices from the client cart
  const listingIds = items.map((i) => i.listingId)
  const { data: listings } = await supabase
    .from('produce_listings')
    .select(
      'id, name, unit, stock_qty, farmer_id, price_tier_1_qty, price_tier_1_price, price_tier_2_qty, price_tier_2_price, price_tier_3_price',
    )
    .in('id', listingIds) as { data: ListingRow[] | null }

  if (!listings || listings.length !== listingIds.length) {
    return bad('One or more items in your cart are no longer available.')
  }

  const listingById = new Map(listings.map((l) => [l.id, l]))
  const rows: Array<Record<string, unknown>> = []
  let total = 0
  // One OTP for the whole batch. Home delivery: the rider does a single
  // handover at the door. Self-pickup: the customer reads it to the farmer at
  // collection. Either way the whole checkout shares one code.
  const sharedHandoverOtp = generateHandoverOtp()
  const deliveryFee = deliveryType === 'home_delivery' ? DELIVERY_FEE_RUPEES : 0

  // Validate first (price + ownership) before we touch any stock. Stock
  // claims happen below with the RPC so two cart submits can't oversell.
  for (const item of items) {
    const listing = listingById.get(item.listingId)
    if (!listing) return bad('Item missing.')
    if (listing.farmer_id !== farmerId) return bad('Items must belong to the same farmer.')

    const unitPrice = getTierPrice(item.qty, {
      priceTier1Qty: listing.price_tier_1_qty,
      priceTier1Price: listing.price_tier_1_price,
      priceTier2Qty: listing.price_tier_2_qty,
      priceTier2Price: listing.price_tier_2_price,
      priceTier3Price: listing.price_tier_3_price,
    })

    const linePrice = unitPrice != null ? Math.round(unitPrice * item.qty) : null
    if (linePrice == null || linePrice <= 0) {
      return bad(`Price not set for ${listing.name}. Please ask the farmer.`)
    }
    total += linePrice

    rows.push({
      farmer_id: farmerId,
      produce_listing_id: listing.id,
      produce_name: listing.name,
      quantity: item.qty,
      unit: listing.unit || 'kg',
      total_price: linePrice,
      buyer_name: consumer.name || 'Buyer',
      buyer_phone: consumer.phone,
      consumer_id: consumer.id,
      idempotency_key: idempotencyKey,
      pickup_location: typeof pickupLocation === 'string' ? pickupLocation.slice(0, 200) : null,
      status: 'pending',
      payment_method: paymentMethod,
      payment_status: 'pending',
      delivery_type: deliveryType,
      delivery_status: deliveryType === 'home_delivery' ? 'unassigned' : null,
      delivery_address: deliveryAddress,
      delivery_landmark: deliveryLandmark,
      delivery_pincode: deliveryPincode,
      delivery_alt_phone: deliveryAltPhone,
      handover_otp: sharedHandoverOtp,
      // Fee is paid once per cart, so we stamp it on the first row only.
      // sum(delivery_fee) and sum(rider_payout) over a batch === one fee.
      delivery_fee: 0,
      rider_payout: 0,
    })
  }

  if (rows.length > 0 && deliveryFee > 0) {
    rows[0].delivery_fee = deliveryFee
    rows[0].rider_payout = deliveryFee
  }

  // Atomic stock claim. decrement_stock returns false if the listing went
  // below zero (or vanished). On any failure we revert prior claims so we
  // don't leak inventory.
  const claimed: Array<{ listingId: string; qty: number }> = []
  const revertClaims = async () => {
    for (const c of claimed) {
      try {
        await supabase.rpc('increment_stock', { p_listing_id: c.listingId, p_qty: c.qty })
      } catch (e) {
        console.error('[YFF] increment_stock revert failed:', e)
      }
    }
  }
  for (const item of items) {
    const listing = listingById.get(item.listingId)!
    const { data: ok, error: rpcErr } = await supabase.rpc('decrement_stock', {
      p_listing_id: item.listingId,
      p_qty: item.qty,
    })
    if (rpcErr) {
      console.error('[YFF] decrement_stock rpc failed:', rpcErr.message)
      await revertClaims()
      return bad('Could not place order. Please try again.', 500)
    }
    if (!ok) {
      await revertClaims()
      return bad(`${listing.name} just sold out. Please reduce the quantity and try again.`)
    }
    claimed.push({ listingId: item.listingId, qty: item.qty })
  }

  const { data: inserted, error: insertErr } = await supabase
    .from('orders')
    .insert(rows)
    .select('id, order_code')

  if (insertErr || !inserted) {
    console.error('[YFF] place-order insert failed:', insertErr?.message)
    // Roll the stock back so the row isn't lost.
    await revertClaims()
    return bad('Could not place order. Please try again.', 500)
  }

  return NextResponse.json({
    ok: true,
    orderIds: inserted.map((r) => r.id),
    orderCodes: inserted.map((r) => (r as { order_code?: string | null }).order_code).filter(Boolean),
    total,
    deliveryFee,
    grandTotal: total + deliveryFee,
  })
}

'use client'

import { useEffect, useState } from 'react'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import ForgotPasswordModal from '@/components/ForgotPasswordModal'

type Mode = 'login' | 'register'

export default function AuthModal() {
  const { closeAuth, login, register } = useConsumerAuth()
  const [mode, setMode] = useState<Mode>('login')
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [password, setPassword] = useState('')
  const [showPw, setShowPw] = useState(false)
  const [loading, setLoading] = useState(false)
  const [error, setError] = useState('')
  const [showForgot, setShowForgot] = useState(false)

  // Lock body scroll while modal is open
  useEffect(() => {
    const prev = document.body.style.overflow
    document.body.style.overflow = 'hidden'
    return () => { document.body.style.overflow = prev }
  }, [])

  const phoneDigits = phone.replace(/\D/g, '').slice(-10)
  const isPhoneValid = phoneDigits.length === 10
  const isPasswordValid = password.length >= 6
  const isNameValid = mode === 'login' ? true : name.trim().length > 0
  const canSubmit = !loading && isPhoneValid && isPasswordValid && isNameValid

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault()
    if (!canSubmit) return
    setLoading(true)
    setError('')
    const result = mode === 'login'
      ? await login({ phone: phoneDigits, password })
      : await register({ name: name.trim(), phone: phoneDigits, password })
    setLoading(false)
    if (!result.ok) setError(result.error)
    // On success the provider closes the modal and re-runs the queued action
  }

  return (
    <div
      className="fixed inset-0 z-[120] flex items-end sm:items-center justify-center bg-black/50"
      role="dialog"
      aria-modal="true"
      onClick={closeAuth}
    >
      <div
        className="w-full sm:max-w-md bg-white rounded-t-3xl sm:rounded-3xl shadow-xl max-h-[90vh] overflow-y-auto"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="sticky top-0 bg-white border-b border-gray-100 px-5 py-4 flex items-center justify-between">
          <h2 className="text-base font-extrabold text-gray-900 leading-tight">
            {mode === 'login' ? 'Log in / లాగిన్' : 'Create account / ఖాతా సృష్టించండి'}
          </h2>
          <button
            type="button"
            onClick={closeAuth}
            aria-label="Close"
            className="text-gray-400 text-2xl leading-none px-2 active:text-gray-600"
          >
            ×
          </button>
        </div>

        <div className="px-5 pt-3">
          <div className="grid grid-cols-2 bg-gray-100 rounded-xl p-1 text-sm font-bold">
            <button
              type="button"
              onClick={() => { setMode('login'); setError('') }}
              className={`py-2 rounded-lg transition-colors ${
                mode === 'login' ? 'bg-white text-green-800 shadow-sm' : 'text-gray-500'
              }`}
            >
              Log in / లాగిన్
            </button>
            <button
              type="button"
              onClick={() => { setMode('register'); setError('') }}
              className={`py-2 rounded-lg transition-colors ${
                mode === 'register' ? 'bg-white text-green-800 shadow-sm' : 'text-gray-500'
              }`}
            >
              Sign up / సైన్ అప్
            </button>
          </div>
        </div>

        <form className="px-5 py-4 space-y-3" onSubmit={handleSubmit}>
          {mode === 'register' && (
            <div>
              <label className="block text-xs font-semibold text-gray-700 mb-1">
                Your name / మీ పేరు
              </label>
              <input
                type="text"
                autoComplete="name"
                value={name}
                onChange={(e) => setName(e.target.value)}
                placeholder="Ramu"
                maxLength={80}
                className="w-full border border-gray-200 rounded-xl px-4 py-3 text-base focus:border-green-500 focus:outline-none"
              />
            </div>
          )}

          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-1">
              Phone number / ఫోన్ నంబర్
            </label>
            <div className="flex items-stretch gap-2">
              <span className="flex items-center px-3 bg-gray-100 rounded-xl text-sm text-gray-600 font-semibold">
                +91
              </span>
              <input
                type="tel"
                inputMode="numeric"
                autoComplete="tel"
                value={phone}
                onChange={(e) => setPhone(e.target.value.replace(/\D/g, '').slice(0, 10))}
                placeholder="98765 43210"
                className="flex-1 border border-gray-200 rounded-xl px-4 py-3 text-base focus:border-green-500 focus:outline-none"
              />
            </div>
          </div>

          <div>
            <label className="block text-xs font-semibold text-gray-700 mb-1">
              Password / పాస్‌వర్డ్
            </label>
            <div className="relative">
              <input
                type={showPw ? 'text' : 'password'}
                autoComplete={mode === 'login' ? 'current-password' : 'new-password'}
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                placeholder={mode === 'login' ? '' : 'At least 6 characters'}
                maxLength={128}
                className="w-full border border-gray-200 rounded-xl px-4 py-3 pr-16 text-base focus:border-green-500 focus:outline-none"
              />
              <button
                type="button"
                onClick={() => setShowPw((v) => !v)}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-xs text-gray-500 font-semibold"
              >
                {showPw ? 'Hide' : 'Show'}
              </button>
            </div>
            {mode === 'register' && (
              <p className="text-[11px] text-gray-500 mt-1">
                Minimum 6 characters / కనీసం 6 అక్షరాలు
              </p>
            )}
          </div>

          {error && (
            <p className="text-sm text-red-600 bg-red-50 border border-red-100 rounded-xl px-3 py-2">
              {error}
            </p>
          )}

          <button
            type="submit"
            disabled={!canSubmit}
            className={`w-full font-bold py-3.5 rounded-xl text-sm ${
              canSubmit ? 'bg-green-700 text-white active:bg-green-800' : 'bg-gray-200 text-gray-500'
            }`}
          >
            {loading
              ? (mode === 'login' ? 'Logging in...' : 'Creating account...')
              : (mode === 'login' ? 'Log in / లాగిన్' : 'Create account / ఖాతా సృష్టించండి')}
          </button>

          {mode === 'login' && (
            <button
              type="button"
              onClick={() => setShowForgot(true)}
              className="w-full text-center text-sm text-green-700 font-semibold underline"
            >
              Forgot Password? / పాస్‌వర్డ్ మర్చిపోయారా?
            </button>
          )}

          <p className="text-[11px] text-gray-500 text-center pt-1 leading-relaxed">
            {mode === 'login'
              ? 'New here? Tap Sign up. / కొత్తవారా? సైన్ అప్ నొక్కండి.'
              : 'Already have an account? Tap Log in. / ఖాతా ఉందా? లాగిన్ నొక్కండి.'}
          </p>
        </form>
      </div>

      {showForgot && (
        <ForgotPasswordModal
          userType="consumer"
          initialPhone={phone}
          onClose={() => setShowForgot(false)}
          onResetComplete={() => setShowForgot(false)}
        />
      )}
    </div>
  )
}

import { createHmac, timingSafeEqual } from 'crypto'
import type { NextRequest, NextResponse } from 'next/server'

// HMAC-signed session token (server-only). Stored in an HTTP-only cookie so
// XSS cannot exfiltrate it. Format: <consumerId>.<issuedAtMs>.<hmacHexBase64url>
//
// We never put consumer name or phone in the token — those live in the DB.
// localStorage holds the public profile copy used purely for UI display, and
// the server re-derives identity from the cookie on every request.

const COOKIE_NAME = 'yff_consumer'
const TOKEN_TTL_MS = 30 * 24 * 60 * 60 * 1000 // 30 days

export function getSessionSecret(): string {
  const secret = process.env.SESSION_SECRET
  if (!secret || secret.length < 32) {
    throw new Error(
      'SESSION_SECRET env var is missing or too short. Set a 32+ char random string in your environment (e.g. `openssl rand -hex 32`).',
    )
  }
  return secret
}

function b64url(buf: Buffer): string {
  return buf.toString('base64').replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '')
}

function sign(payload: string): string {
  const secret = getSessionSecret()
  return b64url(createHmac('sha256', secret).update(payload).digest())
}

export function createSessionToken(consumerId: string): string {
  const issuedAt = Date.now()
  const payload = `${consumerId}.${issuedAt}`
  const sig = sign(payload)
  return `${payload}.${sig}`
}

export type SessionPayload = { consumerId: string; issuedAt: number }

export function verifySessionToken(token: string | undefined | null): SessionPayload | null {
  if (!token) return null
  const parts = token.split('.')
  if (parts.length !== 3) return null
  const [consumerId, issuedAtStr, sig] = parts
  const issuedAt = Number(issuedAtStr)
  if (!consumerId || !Number.isFinite(issuedAt)) return null
  if (Date.now() - issuedAt > TOKEN_TTL_MS) return null

  let expected: string
  try {
    expected = sign(`${consumerId}.${issuedAtStr}`)
  } catch {
    return null
  }
  const a = Buffer.from(sig)
  const b = Buffer.from(expected)
  if (a.length !== b.length) return null
  if (!timingSafeEqual(a, b)) return null
  return { consumerId, issuedAt }
}

export function getConsumerSessionFromRequest(req: NextRequest): SessionPayload | null {
  const token = req.cookies.get(COOKIE_NAME)?.value
  return verifySessionToken(token)
}

export function setSessionCookie(res: NextResponse, consumerId: string): void {
  const token = createSessionToken(consumerId)
  res.cookies.set(COOKIE_NAME, token, {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: Math.floor(TOKEN_TTL_MS / 1000),
  })
}

export function clearSessionCookie(res: NextResponse): void {
  res.cookies.set(COOKIE_NAME, '', {
    httpOnly: true,
    secure: process.env.NODE_ENV === 'production',
    sameSite: 'lax',
    path: '/',
    maxAge: 0,
  })
}

export const CONSUMER_SESSION_COOKIE_NAME = COOKIE_NAME

'use client'

import { useEffect, useState, useCallback, useRef } from 'react'
import Link from 'next/link'
import { supabase } from '@/lib/supabase'
import { useConsumerAuth } from '@/lib/ConsumerAuthContext'
import { compressImage } from '@/lib/imageCompress'
import { DELIVERY_FEE_RUPEES } from '@/lib/delivery-fee'

// Razorpay Checkout is loaded lazily — we only pull the script the first time
// a buyer chooses to pay online, so the rest of the catalogue stays light on
// slow connections.
const RAZORPAY_SCRIPT = 'https://checkout.razorpay.com/v1/checkout.js'

type RazorpayResponse = {
  razorpay_payment_id: string
  razorpay_order_id: string
  razorpay_signature: string
}
type RazorpayOptions = {
  key: string
  amount: number
  currency: string
  name: string
  description?: string
  order_id: string
  handler: (res: RazorpayResponse) => void
  prefill?: { name?: string; contact?: string }
  theme?: { color?: string }
  modal?: { ondismiss?: () => void }
}
type RazorpayInstance = { open: () => void }
declare global {
  interface Window {
    Razorpay?: new (options: RazorpayOptions) => RazorpayInstance
  }
}

function loadRazorpayScript(): Promise<boolean> {
  return new Promise((resolve) => {
    if (typeof window === 'undefined') return resolve(false)
    if (window.Razorpay) return resolve(true)
    const script = document.createElement('script')
    script.src = RAZORPAY_SCRIPT
    script.onload = () => resolve(true)
    script.onerror = () => resolve(false)
    document.body.appendChild(script)
  })
}

type PickupSlots = {
  days: string[]
  time_from: string
  time_to: string
}

export type CartItem = {
  listingId: string
  qty: number
  name: string
  variety?: string
  emoji?: string
  pricePerKg?: number
  priceTier1Qty?: number
  priceTier1Price?: number
  priceTier2Qty?: number
  priceTier2Price?: number
  priceTier3Price?: number
  unit?: string
  stockQty?: number
  farmerId: string
  farmerName: string
  farmerPhone: string
  farmerVillage: string
  farmerSlug: string
  farmerPickupLocations?: string[]
  farmerPickupSlots?: PickupSlots | null
  farmerUpiId?: string
  farmerQrCodeUrl?: string
}

export type CartState = Record<string, CartItem>

export type ConsumerInfo = { name: string; phone: string }

const CART_KEY = 'yff_cart_v1'
const CONSUMER_KEY = 'REDACTED'
const CART_EVENT = 'yff:cart-change'
const UPI_PENDING_KEY = 'yff_upi_pending_v1'
const UPI_LAUNCHED_KEY = 'REDACTED'

const readCart = (): CartState => {
  if (typeof window === 'undefined') return {}
  try {
    const raw = localStorage.getItem(CART_KEY)
    return raw ? (JSON.parse(raw) as CartState) : {}
  } catch {
    return {}
  }
}

const writeCart = (next: CartState) => {
  localStorage.setItem(CART_KEY, JSON.stringify(next))
  window.dispatchEvent(new Event(CART_EVENT))
}

function getActiveTier(qty: number, item: CartItem): { price?: number; isDiscount: boolean } {
  const { priceTier1Qty, priceTier1Price, priceTier2Qty, priceTier2Price, priceTier3Price } = item
  if (priceTier1Qty == null || priceTier1Price == null)
    return { price: item.pricePerKg, isDiscount: false }
  if (qty <= priceTier1Qty)
    return { price: priceTier1Price, isDiscount: false }
  if (priceTier2Qty != null && priceTier2Price != null) {
    if (qty <= priceTier2Qty) return { price: priceTier2Price, isDiscount: true }
    return { price: priceTier3Price ?? priceTier2Price, isDiscount: true }
  }
  if (priceTier3Price != null) return { price: priceTier3Price, isDiscount: true }
  return { price: priceTier1Price, isDiscount: false }
}

export function useCart() {
  const [cart, setCart] = useState<CartState>({})

  useEffect(() => {
    setCart(readCart())
    const sync = () => setCart(readCart())
    window.addEventListener(CART_EVENT, sync)
    window.addEventListener('storage', sync)
    return () => {
      window.removeEventListener(CART_EVENT, sync)
      window.removeEventListener('storage', sync)
    }
  }, [])

  const addItem = useCallback((item: Omit<CartItem, 'qty'>, qty = 1) => {
    const next = { ...readCart() }
    const existing = next[item.listingId]
    const rawQty = Math.max(1, (existing?.qty ?? 0) + qty)
    const newQty = item.stockQty != null ? Math.min(rawQty, item.stockQty) : rawQty
    const merged = { ...item, qty: newQty }
    const { price } = getActiveTier(newQty, merged)
    next[item.listingId] = { ...merged, pricePerKg: price ?? item.pricePerKg }
    writeCart(next)
  }, [])

  const setQty = useCallback((listingId: string, qty: number) => {
    const next = { ...readCart() }
    if (qty <= 0) delete next[listingId]
    else if (next[listingId]) {
      const existing = next[listingId]
      const cappedQty = existing.stockQty != null ? Math.min(qty, existing.stockQty) : qty
      const updated = { ...existing, qty: cappedQty }
      const { price } = getActiveTier(cappedQty, updated)
      next[listingId] = { ...updated, pricePerKg: price ?? updated.pricePerKg }
    }
    writeCart(next)
  }, [])

  const removeItem = useCallback((listingId: string) => {
    const next = { ...readCart() }
    delete next[listingId]
    writeCart(next)
  }, [])

  const clear = useCallback(() => writeCart({}), [])

  const clearFarmer = useCallback((farmerId: string) => {
    const next = { ...readCart() }
    for (const key of Object.keys(next)) {
      if (next[key].farmerId === farmerId) delete next[key]
    }
    writeCart(next)
  }, [])

  const items = Object.values(cart)
  const count = items.reduce((sum, i) => sum + i.qty, 0)

  return { cart, items, count, addItem, setQty, removeItem, clear, clearFarmer }
}

export function useConsumerInfo() {
  const [info, setInfo] = useState<ConsumerInfo>({ name: '', phone: '' })

  useEffect(() => {
    if (typeof window === 'undefined') return
    try {
      const raw = localStorage.getItem(CONSUMER_KEY)
      if (raw) setInfo(JSON.parse(raw))
    } catch { /* ignore */ }
  }, [])

  const save = useCallback((next: ConsumerInfo) => {
    setInfo(next)
    localStorage.setItem(CONSUMER_KEY, JSON.stringify(next))
  }, [])

  return { info, save }
}

type UpiPaymentState = {
  farmerName: string
  farmerVillage: string
  farmerPhone: string
  upiId: string
  qrCodeUrl?: string
  amount: number
  orderIds: string[]
  farmerId: string
  buyerName: string
  buyerPhone: string
  items: Array<{ name: string; variety?: string; emoji?: string; qty: number; unit?: string; pricePerKg?: number }>
  pickupLocation?: string
  pickupDay?: string
}

/* ─── Cart FAB + Sheet ───────────────────────────────── */
export function CartFab() {
  const { items, count } = useCart()
  const [open, setOpen] = useState(false)

  // Auto-open if a UPI payment was in progress (handles page refresh mid-payment)
  useEffect(() => {
    const pending = localStorage.getItem(UPI_PENDING_KEY)
    const launched = localStorage.getItem(UPI_LAUNCHED_KEY)
    if (pending && launched) setOpen(true)
  }, [])

  const handleClose = () => {
    // Wipe both UPI keys — user is explicitly closing, whatever the payment state
    localStorage.removeItem(UPI_LAUNCHED_KEY)
    localStorage.removeItem(UPI_PENDING_KEY)
    setOpen(false)
  }

  if (count === 0 && !open) return null

  return (
    <>
      {!open && (
        <button
          onClick={() => setOpen(true)}
          className="fixed bottom-6 right-4 z-[60] bg-green-700 active:bg-green-800 text-white rounded-full shadow-2xl flex items-center gap-2 pl-4 pr-5 py-3.5"
          style={{ bottom: 'max(24px, env(safe-area-inset-bottom, 24px))' }}
          aria-label="View cart"
        >
          <CartIcon />
          <span className="font-extrabold text-sm">
            {count} {count === 1 ? 'item' : 'items'} / బుట్ట
          </span>
        </button>
      )}
      {open && (
        <CartSheet items={items} onClose={handleClose} />
      )}
    </>
  )
}

/* ─── Cart sheet ─────────────────────────────────────── */
function CartSheet({
  items,
  onClose,
}: {
  items: CartItem[]
  onClose: () => void
}) {
  const { setQty, removeItem, clear, clearFarmer } = useCart()
  const { info, save: saveInfo } = useConsumerInfo()
  const { consumer, requireAuth } = useConsumerAuth()
  const [name, setName] = useState('')
  const [phone, setPhone] = useState('')
  const [paymentMethod, setPaymentMethod] = useState<'cod' | 'upi'>('upi')
  const [showMorePayment, setShowMorePayment] = useState(false)
  // Delivery preference (per checkout). For home_delivery, a flat
  // DELIVERY_FEE_RUPEES is charged once per cart (per farmer group at checkout)
  // and collected by the rider in cash on delivery, regardless of payment method.
  const [deliveryType, setDeliveryType] = useState<'self_pickup' | 'home_delivery'>('self_pickup')
  const [deliveryAddress, setDeliveryAddress] = useState('')
  const [deliveryLandmark, setDeliveryLandmark] = useState('')
  const [deliveryPincode, setDeliveryPincode] = useState('')
  const [deliveryAltPhone, setDeliveryAltPhone] = useState('')
  const [sentFarmers, setSentFarmers] = useState<Record<string, boolean>>({})
  const [pickupByFarmer, setPickupByFarmer] = useState<Record<string, string>>({})
  const [pickupDayByFarmer, setPickupDayByFarmer] = useState<Record<string, string>>({})
  const [toast, setToast] = useState('')
  const [placingUpiOrder, setPlacingUpiOrder] = useState<string | null>(null)
  const [submittingResult, setSubmittingResult] = useState(false)
  // One idempotency key per farmer checkout attempt. Kept until the order
  // actually saves, so a retry after a dropped response reuses the same key
  // and the server returns the existing order instead of placing a new one.
  const idempotencyKeys = useRef<Record<string, string>>({})
  const getIdempotencyKey = (farmerId: string): string => {
    if (!idempotencyKeys.current[farmerId]) {
      idempotencyKeys.current[farmerId] =
        (typeof crypto !== 'undefined' && crypto.randomUUID)
          ? crypto.randomUUID()
          : `${Date.now()}-${Math.random().toString(16).slice(2)}`
    }
    return idempotencyKeys.current[farmerId]
  }
  const [paidDone, setPaidDone] = useState(false)
  // Live UPI IDs and QR codes fetched from DB — always up to date, overrides stale cart data
  const [liveUpiIds, setLiveUpiIds] = useState<Record<string, string>>({})
  const [liveQrUrls, setLiveQrUrls] = useState<Record<string, string>>({})
  // Live COD acceptance per farmer (default false until fetched)
  const [liveCodEnabled, setLiveCodEnabled] = useState<Record<string, boolean>>({})
  const [showUpiAppFallback, setShowUpiAppFallback] = useState(false)
  const [utrNote, setUtrNote] = useState('')
  // Mandatory payment screenshot upload (UPI flow)
  const [proofFile, setProofFile] = useState<File | null>(null)
  const [proofPreview, setProofPreview] = useState('')
  const [proofUploading, setProofUploading] = useState(false)
  const [proofUploaded, setProofUploaded] = useState(false)
  const [proofError, setProofError] = useState('')
  const [cashMode, setCashMode] = useState(false)
  const [switchingToCash, setSwitchingToCash] = useState(false)
  const [upiScreen, setUpiScreen] = useState<UpiPaymentState | null>(null)
  // Razorpay online payment: which farmer group is mid-payment, and whether
  // the latest order was paid online (drives the success copy below).
  const [payingOnline, setPayingOnline] = useState<string | null>(null)
  const [onlinePaid, setOnlinePaid] = useState(false)

  // Refs for use inside event listeners (avoids stale closures)
  const upiScreenRef = useRef<UpiPaymentState | null>(null)
  const autoTriggeredRef = useRef(false)

  useEffect(() => { upiScreenRef.current = upiScreen }, [upiScreen])

  // Update payment status to claimed and clear cart. The farmer is alerted via
  // the realtime subscription on their dashboard — no WhatsApp message opened.
  const triggerPostPayment = useCallback(async (screen: UpiPaymentState, utrRef: string) => {
    setSubmittingResult(true)
    const updateData: Record<string, unknown> = { payment_status: 'pending_confirmation' }
    if (utrRef.trim()) updateData.utr_number = utrRef.trim()
    await Promise.all(
      screen.orderIds.map((id) =>
        supabase.from('orders').update(updateData).eq('id', id)
      )
    )
    clearFarmer(screen.farmerId)
    localStorage.removeItem(UPI_PENDING_KEY)
    localStorage.removeItem(UPI_LAUNCHED_KEY)
    setSubmittingResult(false)
    setPaidDone(true)
  }, [clearFarmer])

  // Keep a ref to triggerPostPayment so visibilitychange handler is never stale
  const triggerPostPaymentRef = useRef(triggerPostPayment)
  useEffect(() => { triggerPostPaymentRef.current = triggerPostPayment }, [triggerPostPayment])

  // On mount: only restore payment screen when UPI app was actually launched.
  // If launched is missing the user just viewed (or closed) the payment screen — don't restore.
  useEffect(() => {
    const pending = localStorage.getItem(UPI_PENDING_KEY)
    const launched = localStorage.getItem(UPI_LAUNCHED_KEY)
    if (!pending || !launched) return
    try {
      const saved = JSON.parse(pending) as UpiPaymentState
      setUpiScreen(saved)
      if (!autoTriggeredRef.current) {
        autoTriggeredRef.current = true
        triggerPostPayment(saved, '')
      }
    } catch { /* ignore corrupt data */ }
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []) // intentionally runs once on mount only

  // Persist upiScreen to localStorage whenever it changes
  useEffect(() => {
    if (upiScreen) localStorage.setItem(UPI_PENDING_KEY, JSON.stringify(upiScreen))
  }, [upiScreen])

  // When user returns from UPI app (no page reload): auto-trigger WhatsApp
  useEffect(() => {
    const handleVisibility = () => {
      if (document.visibilityState !== 'visible') return
      if (!localStorage.getItem(UPI_LAUNCHED_KEY)) return
      if (autoTriggeredRef.current) return
      const screen = upiScreenRef.current
      if (!screen) return
      autoTriggeredRef.current = true
      triggerPostPaymentRef.current(screen, '')
    }
    document.addEventListener('visibilitychange', handleVisibility)
    return () => document.removeEventListener('visibilitychange', handleVisibility)
  }, [])

  // Fetch latest UPI IDs and QR codes for all farmers in cart when sheet opens
  useEffect(() => {
    const farmerIds = [...new Set(items.map((i) => i.farmerId).filter(Boolean))]
    if (farmerIds.length === 0) return
    supabase
      .from('farmers')
      .select('id, upi_id, upi_qr_code_url, cod_enabled')
      .in('id', farmerIds)
      .then(({ data }) => {
        if (!data) return
        const upiMap: Record<string, string> = {}
        const qrMap: Record<string, string> = {}
        const codMap: Record<string, boolean> = {}
        for (const f of data) {
          if (f.upi_id) upiMap[f.id] = f.upi_id
          if (f.upi_qr_code_url) qrMap[f.id] = f.upi_qr_code_url
          codMap[f.id] = f.cod_enabled === true
        }
        setLiveUpiIds(upiMap)
        setLiveQrUrls(qrMap)
        setLiveCodEnabled(codMap)
      })
  }, [items])

  useEffect(() => {
    setName(info.name)
    setPhone(info.phone)
  }, [info])

  // When the consumer logs in, prefer their authenticated profile over any
  // stale form data from the legacy localStorage entry.
  useEffect(() => {
    if (!consumer) return
    if (consumer.name) setName(consumer.name)
    if (consumer.phone) setPhone(consumer.phone)
  }, [consumer])

  // Group items by farmer
  const byFarmer = items.reduce<Record<string, CartItem[]>>((acc, item) => {
    (acc[item.farmerId] = acc[item.farmerId] ?? []).push(item)
    return acc
  }, {})
  const farmerGroups = Object.values(byFarmer)

  const baseDetailsMissing = !name.trim() || phone.replace(/\D/g, '').length < 10
  const deliveryDetailsMissing = deliveryType === 'home_delivery'
    && (deliveryAddress.trim().length < 10 || !/^\d{6}$/.test(deliveryPincode.trim()))
  const detailsMissing = baseDetailsMissing || deliveryDetailsMissing

  const showToast = (msg: string) => {
    setToast(msg)
    setTimeout(() => setToast(''), 3000)
  }

  // Server-authoritative order placement. Prices, buyer identity, and COD
  // permission are computed/checked on the server using the consumer's
  // session cookie — never trusted from the cart's client-side state.
  const placeOrderViaApi = async (
    group: CartItem[],
    paymentMethod: 'upi' | 'cod' | 'razorpay',
  ): Promise<{ ok: true; orderIds: string[]; total: number } | { ok: false; error: string }> => {
    const f = group[0]
    const r = await fetch('/api/orders/place', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      credentials: 'same-origin',
      body: JSON.stringify({
        farmerId: f.farmerId,
        paymentMethod,
        pickupLocation: pickupByFarmer[f.farmerId] || null,
        pickupDay: pickupDayByFarmer[f.farmerId] || null,
        items: group.map((it) => ({ listingId: it.listingId, qty: it.qty })),
        deliveryType,
        deliveryAddress: deliveryType === 'home_delivery' ? deliveryAddress.trim() : null,
        deliveryLandmark: deliveryType === 'home_delivery' ? deliveryLandmark.trim() : null,
        deliveryPincode: deliveryType === 'home_delivery' ? deliveryPincode.trim() : null,
        deliveryAltPhone: deliveryType === 'home_delivery' ? deliveryAltPhone.replace(/\D/g, '').slice(-10) : null,
        idempotencyKey: getIdempotencyKey(f.farmerId),
      }),
    }).catch(() => null)
    if (!r) return { ok: false, error: 'Network error. Please try again.' }
    const json = await r.json().catch(() => ({}))
    if (!r.ok || !json?.ok) return { ok: false, error: json?.error ?? 'Could not place order.' }
    // Order saved — drop the key so a genuinely new order later gets a fresh one.
    delete idempotencyKeys.current[f.farmerId]
    return { ok: true, orderIds: json.orderIds, total: json.total }
  }

  // COD flow: save order via server endpoint. Farmer is alerted via realtime
  // subscription on their dashboard — no WhatsApp opened on the consumer side.
  const handleCodOrderFarmer = async (group: CartItem[]) => {
    if (detailsMissing) return
    saveInfo({ name: name.trim(), phone: phone.trim() })
    const f = group[0]
    const result = await placeOrderViaApi(group, 'cod')
    if (!result.ok) {
      showToast(result.error)
      return
    }
    clearFarmer(f.farmerId)
    setSentFarmers((s) => ({ ...s, [f.farmerId]: true }))
  }

  // UPI flow: save orders via server endpoint, then show the payment screen.
  const handleUpiOrderFarmer = async (group: CartItem[]) => {
    if (detailsMissing) return
    const f = group[0]
    const upiId = liveUpiIds[f.farmerId] ?? f.farmerUpiId ?? ''
    const qrCodeUrl = liveQrUrls[f.farmerId] ?? f.farmerQrCodeUrl
    if (!upiId && !qrCodeUrl) return

    setUtrNote('')
    setShowUpiAppFallback(false)
    setCashMode(false)
    // Fresh UPI session — clear any previous screenshot state
    if (proofPreview) URL.revokeObjectURL(proofPreview)
    setProofFile(null)
    setProofPreview('')
    setProofUploaded(false)
    setProofUploading(false)
    setProofError('')
    saveInfo({ name: name.trim(), phone: phone.trim() })
    setPlacingUpiOrder(f.farmerId)

    const buyerPhone = phone.replace(/\D/g, '').slice(-10)
    const result = await placeOrderViaApi(group, 'upi')
    setPlacingUpiOrder(null)

    if (!result.ok) {
      showToast(result.error)
      return
    }

    autoTriggeredRef.current = false
    setUpiScreen({
      farmerName: f.farmerName,
      farmerVillage: f.farmerVillage,
      farmerPhone: f.farmerPhone,
      upiId,
      qrCodeUrl,
      amount: result.total,
      orderIds: result.orderIds,
      farmerId: f.farmerId,
      buyerName: name.trim(),
      buyerPhone: buyerPhone,
      items: group.map((it) => ({
        name: it.name,
        variety: it.variety,
        emoji: it.emoji,
        qty: it.qty,
        unit: it.unit,
        pricePerKg: it.pricePerKg,
      })),
      pickupLocation: pickupByFarmer[f.farmerId] || undefined,
      pickupDay: pickupDayByFarmer[f.farmerId] || undefined,
    })
  }

  // Online flow (Razorpay): place orders → create a Razorpay order → open
  // Checkout → verify the signature server-side → show success. Money is
  // collected into the platform's Razorpay account, not the farmer's UPI.
  const handleRazorpayOrderFarmer = async (group: CartItem[]) => {
    if (detailsMissing) return
    const f = group[0]
    saveInfo({ name: name.trim(), phone: phone.trim() })
    setPayingOnline(f.farmerId)

    const buyerPhone = phone.replace(/\D/g, '').slice(-10)

    // 1. Place the orders (status pending) on the server.
    const result = await placeOrderViaApi(group, 'razorpay')
    if (!result.ok) {
      setPayingOnline(null)
      showToast(result.error)
      return
    }

    // 2. Load Checkout and create the matching Razorpay order in parallel.
    const [scriptOk, createRes] = await Promise.all([
      loadRazorpayScript(),
      fetch('/api/orders/razorpay/create', {
        method: 'POST',
        credentials: 'same-origin',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ orderIds: result.orderIds }),
      })
        .then((r) => r.json().catch(() => null))
        .catch(() => null),
    ])

    if (!scriptOk || !window.Razorpay) {
      setPayingOnline(null)
      showToast('Could not load the payment screen. Check your connection.')
      return
    }
    if (!createRes?.ok) {
      setPayingOnline(null)
      showToast(createRes?.error ?? 'Could not start payment. Please try again.')
      return
    }

    // Order summary kept for the success screen once payment verifies.
    const summary: UpiPaymentState = {
      farmerName: f.farmerName,
      farmerVillage: f.farmerVillage,
      farmerPhone: f.farmerPhone,
      upiId: '',
      amount: result.total,
      orderIds: result.orderIds,
      farmerId: f.farmerId,
      buyerName: name.trim(),
      buyerPhone,
      items: group.map((it) => ({
        name: it.name,
        variety: it.variety,
        emoji: it.emoji,
        qty: it.qty,
        unit: it.unit,
        pricePerKg: it.pricePerKg,
      })),
    }

    // 3. Open Razorpay Checkout.
    const rzp = new window.Razorpay({
      key: createRes.keyId,
      amount: createRes.amount,
      currency: createRes.currency,
      name: f.farmerName,
      description: 'YourFamilyFarmer order',
      order_id: createRes.razorpayOrderId,
      prefill: { name: name.trim(), contact: buyerPhone },
      theme: { color: '#15803d' },
      modal: {
        ondismiss: () => {
          // Buyer closed Checkout without paying. The orders stay pending so
          // they can pay later from their orders page — nothing to undo here.
          setPayingOnline(null)
          showToast('Payment cancelled. Your order is saved as unpaid.')
        },
      },
      handler: async (res) => {
        // 4. Verify the signature server-side before trusting the payment.
        const vr = await fetch('/api/orders/razorpay/verify', {
          method: 'POST',
          credentials: 'same-origin',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            razorpayOrderId: res.razorpay_order_id,
            razorpayPaymentId: res.razorpay_payment_id,
            razorpaySignature: res.razorpay_signature,
          }),
        })
          .then((r) => r.json().catch(() => null))
          .catch(() => null)

        setPayingOnline(null)
        if (!vr?.ok) {
          showToast(vr?.error ?? 'Payment could not be verified. Please contact support.')
          return
        }
        clearFarmer(f.farmerId)
        setOnlinePaid(true)
        setUpiScreen(summary)
        setPaidDone(true)
      },
    })
    rzp.open()
  }

  const handlePickProof = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const raw = e.target.files?.[0]
    e.target.value = '' // allow re-selecting the same file after error
    if (!raw) return
    if (!raw.type.startsWith('image/')) {
      setProofError('Please pick an image (JPG/PNG/WEBP). / దయచేసి చిత్రం ఎంచుకోండి.')
      return
    }
    if (raw.size > 12 * 1024 * 1024) {
      setProofError('Screenshot too large (max 12MB before compression).')
      return
    }
    setProofError('')
    if (proofPreview) URL.revokeObjectURL(proofPreview)
    setProofUploaded(false)
    const compressed = await compressImage(raw, 1400, 0.75)
    setProofFile(compressed)
    setProofPreview(URL.createObjectURL(compressed))

    // Auto-upload immediately so the user knows it's saved before they tap "I Have Paid"
    if (!upiScreen) return
    setProofUploading(true)
    const fd = new FormData()
    fd.append('orderIds', upiScreen.orderIds.join(','))
    fd.append('file', compressed)
    const r = await fetch('/api/orders/upload-proof', {
      method: 'POST',
      body: fd,
      credentials: 'same-origin',
    }).catch(() => null)
    setProofUploading(false)
    if (!r) {
      setProofError('Upload failed — check your connection and try again.')
      return
    }
    const json = await r.json().catch(() => ({}))
    if (!r.ok || !json?.ok) {
      setProofError(json?.error ?? 'Upload failed.')
      return
    }
    setProofUploaded(true)
  }

  const handlePaymentSuccess = async () => {
    if (!upiScreen) return
    if (!proofUploaded) {
      setProofError('Please attach your payment screenshot first.')
      return
    }
    await triggerPostPayment(upiScreen, utrNote)
  }

  const handleCashOnPickup = async () => {
    if (!upiScreen) return
    setSwitchingToCash(true)
    await Promise.all(
      upiScreen.orderIds.map((id) =>
        supabase.from('orders').update({ payment_method: 'cod', payment_status: 'pending' }).eq('id', id)
      )
    )
    clearFarmer(upiScreen.farmerId)
    localStorage.removeItem(UPI_PENDING_KEY)
    localStorage.removeItem(UPI_LAUNCHED_KEY)
    setSwitchingToCash(false)
    setCashMode(true)
    setPaidDone(true)
  }

  const handleOpenUpiApp = () => {
    localStorage.setItem(UPI_LAUNCHED_KEY, '1')
    setShowUpiAppFallback(false)
    // target="_blank" keeps the current page alive when the OS hands off to the UPI app
    const a = document.createElement('a')
    a.href = 'upi://pay'
    a.target = '_blank'
    a.rel = 'noopener noreferrer'
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    setTimeout(() => setShowUpiAppFallback(true), 2500)
  }

  const handleDownloadQR = async () => {
    if (!upiScreen?.qrCodeUrl) return
    try {
      const response = await fetch(upiScreen.qrCodeUrl)
      const blob = await response.blob()
      const url = URL.createObjectURL(blob)
      const a = document.createElement('a')
      a.href = url
      a.download = `${upiScreen.farmerName.replace(/\s+/g, '_')}_UPI_QR.png`
      document.body.appendChild(a)
      a.click()
      document.body.removeChild(a)
      URL.revokeObjectURL(url)
      showToast('QR saved! / గ్యాలరీకి సేవ్ అయింది')
    } catch {
      showToast('Could not save — please screenshot the QR')
    }
  }

  // Success screen — shown after I Have Paid or Cash on Pickup
  if (upiScreen && paidDone) {
    return (
      <div className="fixed inset-0 z-[200] bg-black/50 flex items-end justify-center">
        <div className="bg-white w-full max-w-md rounded-t-3xl px-6 py-10 flex flex-col items-center text-center gap-4">
          <div className={`w-16 h-16 rounded-full flex items-center justify-center text-3xl ${cashMode ? 'bg-amber-100' : 'bg-green-100'}`}>
