                          : 'border-gray-200 bg-white text-gray-700'
                      }`}
                    >
                      <span className="flex items-center gap-2">
                        <span className="text-base">💳</span>
                        Pay Online (UPI / Card) / ఆన్‌లైన్ చెల్లింపు
                      </span>
                      {paymentMethod === 'upi' && (
                        <span className="text-blue-600 text-base">✓</span>
